/**
 * The seeds are generated by scripts/build-*-seed.mjs. These tests are the
 * contract between those scripts and the app: if a regenerated seed stops
 * matching the domain shape, or a routine row points at an exercise that no
 * longer exists, this fails before the app ever boots.
 */
import { parseExercises, parseRoutines } from '@/lib/storage/serialize';
import exerciseSeed from '../exercises.seed.json';
import routineSeed from '../routine-pablo.seed.json';

const exercises = parseExercises(JSON.stringify(exerciseSeed));
const routines = parseRoutines(JSON.stringify([routineSeed]));

describe('exercise library seed', () => {
  it('parses as valid domain data', () => {
    expect(exercises).not.toBeNull();
  });

  it('carries the full library', () => {
    expect(exercises!.length).toBe(169);
  });

  it('has no duplicate ids', () => {
    const ids = exercises!.map((e) => e.id);
    expect(new Set(ids).size).toBe(ids.length);
  });

  it('only ever pins real YouTube links', () => {
    for (const entry of exercises!) {
      if (entry.videoUrl === null) continue;
      expect(entry.videoUrl).toMatch(/^https:\/\/www\.youtube\.com\/watch\?v=[\w-]{11}$/);
    }
  });

  it('gives every entry a Spanish name, a description and tips', () => {
    for (const entry of exercises!) {
      expect(entry.nameEs.trim()).not.toBe('');
      expect(entry.description).toBeTruthy();
      expect(entry.tips).toBeTruthy();
    }
  });
});

describe('starter routine seed', () => {
  const routine = routines?.[0];

  it('parses as valid domain data', () => {
    expect(routines).not.toBeNull();
    expect(routine).toBeDefined();
  });

  it('keeps the coaching sheet header', () => {
    expect(routine!.athleteName).toBe('Pablo');
    expect(routine!.goal).toBe('brazos');
    expect(routine!.coachName).toBe('Coaching Nach');
  });

  it('has the 6 days of the sheet', () => {
    expect(routine!.days.map((d) => d.focus)).toEqual([
      'Espalda',
      'Pierna',
      'Pecho',
      'Espalda',
      'Brazo',
      'Movilidad y abdomen',
    ]);
  });

  it('has 47 rows, matching the printed sheet', () => {
    const total = routine!.days.reduce((n, day) => n + day.rows.length, 0);
    expect(total).toBe(47);
  });

  it('numbers the days sequentially, without the sheet duplicate', () => {
    expect(routine!.days.map((d) => d.label)).toEqual([
      'Día 1', 'Día 2', 'Día 3', 'Día 4', 'Día 5', 'Día 6',
    ]);
  });

  it('links every row to an exercise that exists in the library', () => {
    const known = new Set(exercises!.map((e) => e.id));
    const dangling: string[] = [];

    for (const day of routine!.days) {
      for (const row of day.rows) {
        if (row.exerciseId === null || !known.has(row.exerciseId)) {
          dangling.push(`${day.label}: ${row.name} -> ${row.exerciseId}`);
        }
      }
    }
    expect(dangling).toEqual([]);
  });

  it('gives every row a pinned video, not just the search fallback', () => {
    const byId = new Map(exercises!.map((e) => [e.id, e]));
    const missing: string[] = [];

    for (const day of routine!.days) {
      for (const row of day.rows) {
        const exercise = row.exerciseId ? byId.get(row.exerciseId) : undefined;
        if (!exercise?.videoUrl) missing.push(`${day.label}: ${row.name}`);
      }
    }
    expect(missing).toEqual([]);
  });

  it('starts with nothing checked off', () => {
    for (const day of routine!.days) {
      expect(day.lastResetOn).toBeNull();
      expect(day.rows.every((row) => !row.done)).toBe(true);
    }
  });

  it('uses icon names, not emoji, for every day', () => {
    for (const day of routine!.days) {
      expect(day.icon).toMatch(/^[a-z0-9-]+$/);
    }
  });
});
